vec3 s = (up.cross(f)).normalize();
vec3 u = f.cross(s);
mat<4, 4> result;
for (int i = 0; i < 3; i++) {
    result[i][0] = s[i];
    result[i][1] = u[i];
    result[i][2] = -f[i];
}
result[0][3] = -s.dot(eye);
result[1][3] = -u.dot(eye);
result[2][3] = f.dot(eye);
result[3][3] = 1;
return result;

